// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.eclipse.rdf4j.sail.lmdb.LmdbPackedRuleDifferentialSupport.check;

import java.io.File;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The finite code/type rewrite must keep the value-equality semantics of the FILTER it replaces: stored numeric codes
 * that value-equal (but are not term-equal to) the code constants must still be counted.
 */
class LmdbCodeTypeTermIdentityTest {

	private static final String QUERY_TEMPLATE = """
			SELECT (COUNT(DISTINCT ?e) AS ?n) WHERE {
			  { ?e a :T1 . ?e :code ?c . VALUES ?t { %1$s } FILTER(?c = ?t || ?c = %2$s) }
			  UNION
			  { ?e a :T2 . ?e :code ?c . VALUES ?t { %1$s } FILTER(?c = ?t || ?c = %2$s) }
			}
			""";

	@Test
	void numericCodesKeepValueEqualStoredTerms(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				:e1 a :T1 ; :code 1.0 .
				:e2 a :T2 ; :code 2 .
				:e3 a :T1 ; :code 5 .
				:e4 a :T2 ; :code 3 .
				""";
		check(dir, data, String.format(QUERY_TEMPLATE, "1 2", "3"), List.of("n=3"));
	}

	@Test
	void mixedDatatypeNumericCodesKeepValueEqualStoredTerms(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
				:e1 a :T1 ; :code "1"^^xsd:int .
				:e2 a :T2 ; :code "02"^^xsd:integer .
				:e3 a :T1 ; :code 3.0 .
				:e4 a :T2 ; :code 4 .
				""";
		check(dir, data, String.format(QUERY_TEMPLATE, "1 2", "3"), List.of("n=3"));
	}

	@Test
	void stringCodesStillCountEveryMatchingEntity(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				:e1 a :T1 ; :code "DX-200" .
				:e2 a :T2 ; :code "DX-201" .
				:e3 a :T1 ; :code "DX-999" .
				:e4 a :T2 ; :code "DX-202" .
				""";
		check(dir, data, String.format(QUERY_TEMPLATE, "\"DX-200\" \"DX-201\"", "\"DX-202\""), List.of("n=3"));
	}
}
